// === Tab: mySketch ===
// こっほ
// まず三角形。

let myShader;
let lapse = 0;    // mouse timer

let vs =
"precision mediump float;" +
"attribute vec3 aPosition;" +
"void main(void){" +
"  gl_Position = vec4(aPosition, 1.0);" +
"}";

let fs =
"precision mediump float;" +
"uniform vec2 u_resolution;" +
"uniform vec2 u_mouse;" +
"uniform float u_time;" +
"const float pi = 3.14159;" +
// 外の色と中の色
"const vec3 outerColor = vec3(0.8, 0.5, 0.4);" +
"const vec3 innerColor = vec3(0.2, 0.8, 0.4);" +
// 回転
"void rotate(inout vec2 p, float phase){" +
"  float t = phase * -2.0 * pi;" +
"  p *= mat2(cos(t), sin(t), -sin(t), cos(t));" +
"}" +
// ランダム
"const vec2 r_vector = vec2(12.9898, 78.233);" +
"const float r_coeff = 43758.5453123;" +
"float random(vec2 st){" +
"  return fract(sin(dot(st.xy, r_vector)) * r_coeff);" +
"}" +
// 2Dランダム
"const vec2 r_vec_20 = vec2(221.94, 315.86);" +
"const vec2 r_vec_21 = vec2(174.54, 413.89);" +
// 2Dランダムベクトル(-1.0～1.0)
"vec2 random2(vec2 st){" +
"  vec2 v;" +
"  v.x = sin(dot(st, r_vec_20)) * r_coeff;" +
"  v.y = sin(dot(st, r_vec_21)) * r_coeff;" +
"  return -1.0 + 2.0 * fract(v);" +
"}" +
"vec3 getBackground(vec2 p){" +
"  p = abs(p);" +
"  return vec3(mix(vec3(0.0, 0.25, 0.5), vec3(0.9), 0.5 * (p.x + p.y)));" +
"}" +
// hsb to rgb.
"vec3 getRGB(float h, float s, float b){" +
"    vec3 c = vec3(h, s, b);" +
"    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);" +
"    rgb = rgb * rgb * (3.0 - 2.0 * rgb);" +
"    return c.z * mix(vec3(1.0), rgb, c.y);" +
"}" +
// 準備。
// トライフォースのてっぺんに移す
// 左なら右に移し、y=(1/√3)xで折り返す。
"void preparation(inout vec2 p){" +
"  p.x = abs(p.x);" +
"  const vec2 e = vec2(-0.5, 0.866);" +
"  p = p - 2.0 * min(0.0, dot(p, e)) * e;" +
"  p.y -= 0.25;" +
"  p *= 2.3094;" + // 4/√3.
"}" +
// イテレート
// (1,0), (-1,0), (0,√3)の三角形を常に考え続ける。
// イテレーション終了時の回数を返すといいかも。
// outerの場合に第4成分を-1.0にすることでアウターカラーのムラをなくせる
"vec4 getKoch(inout vec2 p, float limit){" +
"  preparation(p);" +
"  const vec2 e = vec2(0.866, -0.5);" +
"  const vec2 c = vec2(0.33333, 0.0);" + // 折り返し用
"  const vec2 u = vec2(1.0, 0.0);" +
"  for(float i = 0.0; i < 5.0; i += 1.0){" +
"    if(p.y < 0.0){ return vec4(innerColor, i); }" +
"    p.x = abs(p.x);" +
"    if(p.y > 0.57735 || p.y > 1.73205 * (1.0 - p.x)){ return vec4(vec3(0.0), -1.0); }" +
// 折り返す
"    if(p.y > 1.73205 * p.x - 0.57735){" +
"      p -= c;" +
"      p = p - 2.0 * min(0.0, dot(p, e)) * e;" +
"      p += c;" +
"    }" +
"    if(i == limit){ break; }" +
"    p = u + 3.0 * (p - u);" +
"  }" +
"  return vec4(vec3(0.0), -1.0);" +
"}" +
"void main(void){" +
"  vec2 p = (gl_FragCoord.xy - u_resolution) / min(u_resolution.x, u_resolution.y);" +
"  rotate(p, u_time * 0.1);" +
"  vec3 bg = getBackground(p);" +
"  p *= 0.7;" +
"  vec2 q = p + vec2(0.03);" +
"  vec3 col = outerColor;" +
"  float alpha = 1.0;" +
"  vec4 data = getKoch(p, floor(mod(u_time, 5.0)));" +
"  vec4 shadow = getKoch(q, floor(mod(u_time, 5.0)));" +
"  if(data.w < 0.0){" +
// 外側
"    if(shadow.w < 0.0){" +
"      col = bg;" +
"    }else{" +
"      col = mix(shadow.xyz, vec3(0.1, 0.2, 1.0), 0.1 + 0.2 * shadow.w);" +
"      col = mix(col, vec3(0.9), p.y * 0.5);" +
"      alpha = 0.5;" +
"    }" +
"  }else{" +
// 内側
"    col = mix(data.xyz, vec3(0.1, 0.2, 1.0), 0.1 + 0.2 * data.w);" +
"    col = mix(col, vec3(0.9), p.y * 0.8);" +
"  }" +
"  gl_FragColor = vec4(col, alpha);" +
"}";

function setup(){
  // createCanvas(1112, 834, WEBGL);
  createCanvas(1112*2, 834*2, WEBGL);
	myShader = createShader(vs, fs);
  shader(myShader);
  //noLoop();
}

function draw(){
  myShader.setUniform("u_resolution", [width, height]);
  myShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
  myShader.setUniform("u_time", millis() / 1000);
  quad(-1, -1, -1, 1, 1, 1, 1, -1);
}

function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 500){
    save('pix.jpg');
    lapse = millis();
  } 
}

